let family='all';function renderConsoles(){const q=$('#console-search').value.trim().toLowerCase(),rows=consoles.filter(x=>(family==='all'||x.family===family)&&`${x.system} ${x.game}`.toLowerCase().includes(q));$('#console-results').innerHTML=rows.map(x=>`<article class="console-card"><div class="console-card-head"><div><span class="console-family">${x.family}</span><h3>${esc(x.game)}</h3><p>${esc(x.system)}</p></div><span class="console-badge">${esc(x.badge)}</span></div><div class="console-modes">${x.modes.map(m=>`<div><span><strong>${esc(m[0])}</strong><small>${esc(m[1])}</small></span><strong>${esc(m[2])}</strong></div>`).join('')}</div><a href="${esc(x.source)}" target="_blank" rel="noopener noreferrer">View source</a></article>`).join('')||'<p class="console-empty">No matching console game. Try another search.</p>'}
